import{z as B,x as A,o as r,c as m,q as o,j as l,D as e,d as t,s,S as n,b as E}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"波动缩放仓位","description":"","frontmatter":{"title":"波动缩放仓位","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/vol-scale-cta.md","filePath":"quant/vol-scale-cta.md","lastUpdated":1791063341000}'),p={name:"quant/vol-scale-cta.md"};function d(h,a,u,D,g,c){const i=A("Mermaid");return r(),m("div",null,[a[2]||(a[2]=o('<h1 id="波动缩放仓位" tabindex="-1">波动缩放仓位 <a class="header-anchor" href="#波动缩放仓位" aria-label="Permalink to &quot;波动缩放仓位&quot;">​</a></h1><div class="epigraph"><p>时间序列动量把仓位写成趋势符号除以已实现波动再乘目标风险；没有这一层，高波合约会主导组合，夏普与左尾都会变差。</p><footer>—— Moskowitz, Ooi &amp; Pedersen, Time Series Momentum, Journal of Financial Economics, 2012</footer></div><p><a href="/quant/breakout-ma">上一课</a>把突破、均线与过去超额符号收成同一趋势赌注的三种滤波器；比较必须在同一波动缩放下进行。缺口是那个「同一波动缩放」还没写：方向来自趋势，盈亏的尺度来自仓位。本课写 CTA 语境下的 \\(1/\\hat\\sigma\\)：它改变权重与杠杆路径，不创造新的方向信息。不重讲通道止损。后课跨资产相关默认已经读完：危机 alpha 有一部分来自组合层目标波动，而不是 \\(\\mathrm{sign}(\\cdot)\\)。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>不加缩放时，名义等权的期货组合方差由原油、天然气、股指来决定，汇率与短端利率几乎不占风险。趋势信号即使在汇率上同样有效，也表现不出来。问题是把每条合约的风险贡献拉齐，使组合更接近「信息的等权」而不是「波动的等权」。第二个问题是时间序列上的杠杆：\\(\\hat\\sigma\\) 低时加杠杆，\\(\\hat\\sigma\\) 高时去杠杆。这既是对波动聚类的响应，也是一条与经纪商保证金平行的减仓规则，会在拥挤时变成市场供给。</p><p>识别上必须区分三种「波动」：合约已实现波动、策略组合已实现波动、隐含波动。CTA 主规则用第一种估权重；产品说明书盯第二种；用 VIX 对股指腿做第三种择时是额外赌注。混用而不声明，回测不可复现。</p><p><span class="marginnote">「已实现波动」是回头看过去一段时间真实走过的波动，用日收益算出来；「隐含波动」是期权市场对未来的报价。可以把它想象成后视镜与前挡风玻璃：CTA 用后视镜开车，但前方的坑只有前挡风玻璃能提前照见。</span></p><h3 id="合约层-目标波动除以估计波动" tabindex="-1">合约层：目标波动除以估计波动 <a class="header-anchor" href="#合约层-目标波动除以估计波动" aria-label="Permalink to &quot;合约层：目标波动除以估计波动&quot;">​</a></h3><p>MOP 的形式是</p> \\[w_{i,t}=\\mathrm{sign}(r_{t-L,t}^{i})\\cdot\\frac{\\sigma_{\\mathrm{tgt}}}{\\hat\\sigma_{i,t}}. \\]<p>\\(\\hat\\sigma\\) 常用日收益的 EWMA 或过去约两个月实现波动，年化时注意交易日数。\\(\\sigma_{\\mathrm{tgt}}\\) 是规则参数，不是预测。估计窗太短，仓位抖动、换手上升；太长，对危机中的波动跳升反应迟钝。应预先固定衰减因子或窗口，并报告有无缩放两列夏普、偏度与最大回撤。缩放会改变有效杠杆，基准必须是同等目标风险下的被动组合，而不是未杠杆的现货指数。</p><p><span class="marginnote">波动缩放不是 Kelly。Kelly 用期望与方差决定最优分数；这里的 \\(\\mathrm{sign}\\) 不含幅度，期望被当成只来自方向。把 \\(1/\\hat\\sigma\\) 解释成增长最优，会在信号失效时仍然加满杠杆。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>估计：对数收益、去周末与节假日、对跳空单独处理。股指与商品在公告日的实现波动会上升，EWMA 会在事后加一脚减速；这是特征还是缺陷，取决于你是否愿意在跳完之后还留着危机前的杠杆。上限：对 \\(\\hat\\sigma\\) 设地板，防止平静期杠杆无穷大；对 \\(|w|\\) 设天花板，防止单合约占满保证金。组合层再按总波动缩放到产品目标，避免「合约层已经 40%、十个同向合约合成远超说明书」。</p><p>诊断：把 PnL 拆成「方向对了」与「杠杆对了」。危机月里若方向对但缩放把名义砍光，危机 alpha 会小于未缩放版本——这不是 bug，是规则。应同时给投资者看：未缩放、仅合约缩放、合约加组合缩放三列。与风险平价的关系：等风险权重是截面上的 \\(1/\\sigma\\)；vol targeting 是时间上的 \\(1/\\sigma\\)。CTA 常常两者都做，杠杆对总波动的弹性大约是两层相乘。</p><h3 id="策略层缩放与合约层缩放不是同一开关" tabindex="-1">策略层缩放与合约层缩放不是同一开关 <a class="header-anchor" href="#策略层缩放与合约层缩放不是同一开关" aria-label="Permalink to &quot;策略层缩放与合约层缩放不是同一开关&quot;">​</a></h3><p>Barroso–Santa-Clara 对股票 WML 的缩放，针对的是动量策略自身的波动爆发（动量崩溃）。CTA 的合约层缩放针对的是资产异质波动。两者可以同时开：先按合约 \\(1/\\sigma_i\\) 配权，再按组合 \\(\\sigma_{\\mathrm{port}}\\) 调总杠杆。只开后者、合约仍等名义，高波商品依旧主导。只开前者、不开总杠杆上限，同向趋势时产品波动会漂。工程上这是两个旋钮，回测应做 \\(2\\times 2\\)，而不是一个「vol target」标签。</p>',17)),(r(),l(n,null,{default:e(()=>[s(i,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20SIG%5B%22%E8%B6%8B%E5%8A%BF%E7%AC%A6%E5%8F%B7%22%5D%20--%3E%20W1%5B%22%E5%90%88%E7%BA%A6%E4%BB%93%E4%BD%8D%20%E2%88%9D%201%2F%CF%83_i%22%5D%0A%20%20VOLI%5B%22%E5%90%88%E7%BA%A6%E5%AE%9E%E7%8E%B0%E6%B3%A2%E5%8A%A8%22%5D%20--%3E%20W1%0A%20%20W1%20--%3E%20PORT%5B%22%E5%90%88%E6%88%90%E7%BB%84%E5%90%88%22%5D%0A%20%20VOLP%5B%22%E7%BB%84%E5%90%88%E5%AE%9E%E7%8E%B0%E6%B3%A2%E5%8A%A8%22%5D%20--%3E%20W2%5B%22%E6%80%BB%E6%9D%A0%E6%9D%86%E6%8B%89%E5%88%B0%E4%BA%A7%E5%93%81%E7%9B%AE%E6%A0%87%22%5D%0A%20%20PORT%20--%3E%20W2%0A%20%20W2%20--%3E%20CAP%5B%22%E5%90%8D%E4%B9%89%E4%B8%8E%E4%BF%9D%E8%AF%81%E9%87%91%E4%B8%8A%E9%99%90%22%5D%0A%20%20CAP%20--%3E%20PNL%5B%22%E8%B7%AF%E5%BE%84%E4%BE%9D%E8%B5%96%20PnL%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[t("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"资产收益有波动聚类：高波动后往往仍高。若条件夏普在高波动状态更低（Moreira–Muir 的方向），则降低杠杆提高无条件夏普。趋势策略还有一条特有机制：波动上升常与转折或拥挤减仓同时发生，不加缩放会在最差流动性上留着最大名义。缩放提前减仓，牺牲趋势加速段的一部分利润，换更薄的左尾。",-1)),a[5]||(a[5]=E("p",null,[E("span",{class:"marginnote"},"代入数字看这条规则多「狠」：目标波动 15%、当前 \\(\\hat\\sigma=5\\%\\) 时，仓位是 \\(15/5=3\\) 倍名义；波动跳到 30%，仓位自动砍到 \\(15/30=0.5\\) 倍。波动翻 6 倍，杠杆缩 6 倍，这张合约占组合的风险贡献基本不变。")],-1)),a[6]||(a[6]=E("p",null,[t("反向成本是「波动挤压」：平静期加杠杆，突然跳升时所有 vol target 账户一起卖，见"),E("a",{href:"/quant/crowding-spiral"},"拥挤螺旋"),t("。因此缩放改善的是单策略在外生波动下的风险调整收益；当策略本身大到推动波动，缩放变成内生反馈。容量评估必须把同业规则相关算进去。")],-1)),(r(),l(n,null,{default:e(()=>[s(i,{id:"mermaid-60",class:"mermaid",graph:"flowchart%20TD%0A%20%20CALM%5B%22%E5%B9%B3%E9%9D%99%E6%9C%9F%EF%BC%9A%CF%83%CC%82%20%E5%A4%84%E4%BA%8E%E4%BD%8E%E4%BD%8D%22%5D%20--%3E%20LEV%5B%221%2F%CF%83%CC%82%20%E8%A7%84%E5%88%99%E7%BB%99%E5%87%BA%E9%AB%98%E6%9D%A0%E6%9D%86%22%5D%0A%20%20LEV%20--%3E%20JUMP%5B%22%E6%B3%A2%E5%8A%A8%E7%AA%81%E7%84%B6%E8%B7%B3%E5%8D%87%22%5D%0A%20%20JUMP%20--%3E%20EST%5B%22EWMA%20%E4%BC%B0%E8%AE%A1%E5%BF%AB%E9%80%9F%E4%B8%8A%E8%B0%83%22%5D%0A%20%20EST%20--%3E%20CUT%5B%22%E8%A7%84%E5%88%99%E8%87%AA%E5%8A%A8%E5%87%8F%E4%BB%93%E3%80%81%E7%A0%8D%E5%90%8D%E4%B9%89%22%5D%0A%20%20CUT%20--%3E%20CROWD%5B%22%E5%A4%A7%E9%87%8F%20vol%20target%20%E8%B4%A6%E6%88%B7%E5%90%8C%E5%90%91%E5%8D%96%E5%87%BA%22%5D%0A%20%20CROWD%20--%3E%20IMPACT%5B%22%E6%88%90%E4%BA%A4%E5%86%B2%E5%87%BB%E8%BF%9B%E4%B8%80%E6%AD%A5%E5%8E%8B%E4%BD%8E%E4%BB%B7%E6%A0%BC%22%5D%0A%20%20IMPACT%20--%3E%20FEED%5B%22%E5%B7%B2%E5%AE%9E%E7%8E%B0%E6%B3%A2%E5%8A%A8%E5%86%8D%E5%BA%A6%E4%B8%8A%E5%8D%87%22%5D%0A%20%20FEED%20--%3E%20EST%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=o('<h3 id="估计误差会写成错误的杠杆" tabindex="-1">估计误差会写成错误的杠杆 <a class="header-anchor" href="#估计误差会写成错误的杠杆" aria-label="Permalink to &quot;估计误差会写成错误的杠杆&quot;">​</a></h3><p>\\(\\hat\\sigma\\) 向下偏，杠杆向上偏。用未调整的已实现波动、忽略隔夜、或在涨跌停下把零收益当成低波动，都会在国内期货上系统性加杠杆。隐含波动通常高于已实现，若用 IV 做缩放会整体更保守，并引入波动风险溢价的暴露。选择哪一种要写进说明书：CTA 传统用已实现，因为信号是价格趋势，风控也想跟已实现风险走；用 IV 是另一种产品。</p><p><span class="marginnote">目标波动定到 20% 再宣传「与论文同样的 40% 合约目标」，只是把组合层缩放藏进了营销。投资者看到的回撤由最终产品杠杆决定。信息比不会因为你把目标写大而提高。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把波动缩放叫做新的 alpha 因子。不要在已经缩放后再用未缩放多头当基准。不要把 VIX 择时、合约 \\(1/\\sigma\\) 与组合目标三个开关搅在一个回测里只报最好的一列。保证金与变异保证金已经在高波时要钱，vol target 是额外的自选减仓；两者同日触发时，执行计划要预先错开，避免与清算盘抢价。</p><p>与 <a href="/quant/frazzini-bab">BAB</a> 的差别：BAB 利用的是杠杆约束造成的 beta 定价错误；CTA 缩放是主动选择风险暴露。不要把低波超配与趋势 vol target 写成同一个「低波动溢价」。A 股与商品的涨跌停使 \\(\\hat\\sigma\\) 在极限日失真，应使用限价调整或跳过该日的稳健估计。</p><p><span class="marginnote">常见误区：初学者容易以为 \\(\\hat\\sigma\\) 低就等于安全，可以放心把杠杆加满。实际上平静往往是大跳升的前奏（这正是波动聚类的含义），所以才要给 \\(\\hat\\sigma\\) 设地板、给杠杆设天花板，把最坏一天的名义提前锁住。</span></p><p><span class="marginnote">出处：Moskowitz, Ooi &amp; Pedersen, <em>Time Series Momentum</em>, JFE, 2012。策略波动管理见 Barroso and Santa-Clara, Journal of Financial Economics, 2015；Moreira and Muir, Journal of Finance, 2017。保证金螺旋见 Brunnermeier and Pedersen, RFS, 2009。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>CTA 的波动缩放把仓位写成方向除以已实现波动，使风险贡献可比较，并在波动上升时自动降杠杆。</li><li>合约层 \\(1/\\sigma_i\\) 与组合层目标波动是两个开关；危机 alpha 有一部分来自后者而非符号函数。</li><li>缩放改善风险调整收益，但在拥挤的 vol target 同步减仓时会自我强化冲击。</li><li>估计窗、地板、上限与是否用隐含波动必须预先固定，并报告有无缩放的对照。</li><li>出处：Moskowitz et al., 2012；Barroso–Santa-Clara, 2015；Moreira–Muir, 2017。</li></ul>',10))])}const f=B(p,[["render",d]]);export{T as __pageData,f as default};
